import json
from collections import Counter
modules=[]; Q=[]
def module(id,title,emoji,lead,body,bullets,example,image,glossary):
 modules.append(dict(id=id,title=title,emoji=emoji,lead=lead,body=body,bullets=bullets,example=example,image=image,glossary=glossary))
def add(mod,typ,afb,prompt,answer,solution,options=None,hint='',bonus=False,unit='',tolerance=.011,pairs=None,items=None,groups=None):
 d=dict(id=f'{mod}-{sum(1 for q in Q if q["module"]==mod)+1:02}',module=mod,type=typ,afb=afb,prompt=prompt,answer=answer,solution=solution,hint=hint,bonus=bonus)
 for k,v in dict(options=options,unit=unit,tolerance=tolerance,pairs=pairs,items=items,groups=groups).items():
  if v is not None and v!='': d[k]=v
 Q.append(d)
def n(m,a,p,ans,sol,**kw):add(m,'number',a,p,ans,sol,unit=kw.pop('unit','€'),**kw)
def s(m,a,p,ans,options,sol,**kw):add(m,'single',a,p,ans,sol,options=options,**kw)
def mult(m,a,p,ans,options,sol,**kw):add(m,'multi',a,p,ans,sol,options=options,**kw)
def tf(m,a,p,ans,sol,**kw):add(m,'truefalse',a,p,ans,sol,**kw)
def tx(m,a,p,sol,**kw):add(m,'text',a,p,None,sol,**kw)
def order(m,a,p,items,sol,**kw):add(m,'order',a,p,items,sol,items=items,**kw)
def match(m,a,p,pairs,sol,**kw):add(m,'match',a,p,pairs,sol,pairs=pairs,**kw)
def drag(m,a,p,groups,items,answer,sol,**kw):add(m,'drag',a,p,answer,sol,groups=groups,items=items,**kw)

module('kosten','Kostenträger & Zurechenbarkeit','📦','Was gehört zu einem Smartphone-Halter?',
 'Die fiktive **LoopLab GmbH** aus Leipzig fertigt modulare Smartphone- und Laptop-Halter aus Holz und Aluminium. **Einzelkosten** lassen sich einem Kostenträger direkt zuordnen. **Gemeinkosten** lassen sich nicht direkt einem einzelnen Produkt zuordnen und werden häufig über Schlüssel verteilt.',
 ['**Einzelkosten:** direkt einem Produkt oder Auftrag zurechenbar.','**Gemeinkosten:** nur indirekt zurechenbar, z. B. Hallenmiete.','**Kostenträger:** Produkt bzw. Auftrag, dessen Kosten ermittelt werden.'],
 'Beispiel: Aluminium je FlexDock 10 € = Einzelkosten. Die Hallenmiete von 2.000 € pro Monat = Gemeinkosten.','kostenmatrix',['Einzelkosten','Gemeinkosten','Kostenträger'])
s('kosten',1,'Welche Kosten sind im Regelfall direkt einem FlexDock zurechenbar?','Aluminium für ein FlexDock',['Hallenmiete','Aluminium für ein FlexDock','Verwaltungsgehalt'], 'Aluminium für ein FlexDock ist mengenmäßig erfassbar und direkt zurechenbar.')
tf('kosten',1,'Gemeinkosten lassen sich einem bestimmten Produkt ohne Verteilungsschlüssel direkt zurechnen.',False,'Falsch. Gemeinkosten werden mehreren Produkten gemeinsam verursacht; eine direkte Einzelzurechnung ist regelmäßig nicht möglich.')
match('kosten',2,'Ordnen Sie die Kosten der passenden Kostenart zu.',{'Aluminium für FlexDock':'Einzelkosten','Hallenmiete':'Gemeinkosten','Akkordlohn für FlexDock':'Einzelkosten','Verwaltungsgehalt':'Gemeinkosten'},'Aluminium und Akkordlohn sind direkt zurechenbar; Hallenmiete und Verwaltung betreffen mehrere Produkte.')
n('kosten',2,'Ein Produkt verursacht 12 € Material- und 8 € Fertigungseinzelkosten. Ermitteln Sie die Einzelkosten je Stück.',20,'Einzelstückkosten = 12 € (Materialeinzelkosten) + 8 € (Fertigungseinzelkosten) = **20 €/Stück**.',unit='€/Stück')
drag('kosten',2,'Ziehen oder tippen Sie die Kosten in die richtige Kategorie.',['Einzelkosten','Gemeinkosten'],['Auftragsspezifisches Bauteil','Büromiete','Akkordlohn','Gemeinsamer Maschinenstrom'],{'Auftragsspezifisches Bauteil':'Einzelkosten','Büromiete':'Gemeinkosten','Akkordlohn':'Einzelkosten','Gemeinsamer Maschinenstrom':'Gemeinkosten'},'Direkt zurechenbare Kosten → Einzelkosten; sonst → Gemeinkosten.')
mult('kosten',2,'Welche Aussagen sind korrekt?',['Einzelkosten können fix sein.','Gemeinkosten können variabel sein.'],['Einzelkosten können fix sein.','Gemeinkosten sind immer fix.','Gemeinkosten können variabel sein.','Einzelkosten sind immer variabel.'],'Die Zurechenbarkeit und das Kostenverhalten sind zwei voneinander unabhängige Merkmale.')
tx('kosten',3,'Erläutern Sie, weshalb die monatliche Hallenmiete nicht automatisch einem einzelnen FlexDock zugerechnet werden kann.','Die Halle dient mehreren Produkten; eine direkte Zuordnung wäre nicht eindeutig. Daher erfolgt die Verteilung als Gemeinkosten über einen geeigneten Schlüssel.')
tx('kosten',3,'Beurteilen Sie, ob eine feste, nur für den „BikeClip“ gezahlte Produktlizenz als Einzelkosten erfasst werden kann.','Ja. Die feste Lizenz ist einem bestimmten Produkt direkt zurechenbar und kann als **fixe Einzelkosten** klassifiziert werden.')
tx('kosten',3,'Bonus: Warum sollte das Unternehmen Gemeinkosten bei einer Stückkalkulation nicht einfach weglassen?','Dann würden die Selbstkosten zu niedrig ausgewiesen und die langfristige Preisuntergrenze fehlerhaft bestimmt.',bonus=True)
match('kosten',2,'Bonus: Ordnen Sie die Fachbegriffe zu.',{'Kostenträger':'Produkt oder Auftrag','Zuschlagssatz':'Schlüssel zur Kostenverteilung','Einzelkosten':'direkt zurechenbar'},'Die Zuordnung erleichtert die spätere Zuschlagskalkulation.',bonus=True)

module('verhalten','Fixe und variable Kosten','🏭','Welche Kosten bewegen sich mit der Produktion?',
 '**Variable Kosten** ändern sich mit der Beschäftigung. **Fixe Kosten** bleiben in einem festgelegten Beschäftigungsbereich konstant. Im Kurs nehmen wir – außer wenn ausdrücklich anders angegeben – **proportionale variable Kosten** an; die variablen Stückkosten bleiben dann gleich.',
 ['**Variable Einzelkosten:** z. B. Aluminium und Akkordlohn.','**Variable Gemeinkosten:** z. B. verbrauchsabhängiger Maschinenstrom.','**Fixe Einzelkosten:** z. B. feste produktbezogene Lizenz.','**Fixe Gemeinkosten:** z. B. Hallenmiete, Verwaltung.'],
 'Beispiel: 400 Stück · 22 €/Stück (variable Kosten) = 8.800 € variable Gesamtkosten; 6.400 € monatliche Fixkosten bleiben gleich.','kostenmatrix',['Fixkosten','Variable Kosten','Variable Einzelkosten','Variable Gemeinkosten','Fixe Einzelkosten','Fixe Gemeinkosten'])
s('verhalten',1,'Welche Position ist typischerweise fix?','Monatliche Hallenmiete',['Verbrauchsabhängiger Maschinenstrom','Monatliche Hallenmiete','Rohmaterial je Stück'],'Die Hallenmiete fällt in der Regel auch ohne Produktion an.')
tf('verhalten',1,'Bei proportionalem Verlauf bleiben die variablen Stückkosten konstant.',True,'Richtig. Proportionale variable Gesamtkosten steigen im gleichen Verhältnis wie die Stückzahl.')
drag('verhalten',2,'Ordnen Sie die Kosten der Vierfeldermatrix zu.',['variable Einzelkosten','fixe Einzelkosten','variable Gemeinkosten','fixe Gemeinkosten'],['Fertigungsmaterial','Pauschale Produktlizenz','Verbrauchsabhängiger Hallenstrom','Monatliche Büromiete'],{'Fertigungsmaterial':'variable Einzelkosten','Pauschale Produktlizenz':'fixe Einzelkosten','Verbrauchsabhängiger Hallenstrom':'variable Gemeinkosten','Monatliche Büromiete':'fixe Gemeinkosten'},'Einzel/Gemein: Zurechenbarkeit. Fix/variabel: Abhängigkeit von der Menge.')
n('verhalten',2,'Bei 300 Stück betragen variable Gesamtkosten 6.600 €. Bestimmen Sie die variablen Stückkosten.',22,'Variable Stückkosten = 6.600 € (variable Gesamtkosten) ÷ 300 Stück (Menge) = **22 €/Stück**.',unit='€/Stück')
n('verhalten',2,'Die variablen Stückkosten betragen 22 €. Wie hoch sind die variablen Gesamtkosten bei 500 Stück?',11000,'Variable Gesamtkosten = 22 €/Stück (variable Stückkosten) · 500 Stück (Menge) = **11.000 €**.')
match('verhalten',2,'Ordnen Sie Veränderungen bei proportionalem Kostenverlauf zu.',{'Produktionsmenge verdoppelt':'Variable Gesamtkosten verdoppeln sich','Produktion stoppt':'Variable Gesamtkosten fallen auf 0 €','Menge steigt innerhalb der Kapazität':'Fixkosten bleiben gleich'},'Dies gilt bei proportionalen variablen Kosten und konstanten Fixkosten im betrachteten Bereich.')
tx('verhalten',3,'Begründen Sie, weshalb eine Spezialmaschine gleichzeitig fixe Einzelkosten verursachen kann.','Ist die Maschine ausschließlich einem Produkt zugeordnet, sind ihre zeitabhängigen Abschreibungen diesem Produkt direkt zurechenbar (Einzelkosten) und beschäftigungsunabhängig (fix).')
tx('verhalten',3,'Beurteilen Sie die Aussage: „Alle Gemeinkosten sind Fixkosten.“','Falsch. Gemeinkosten können variabel (Maschinenstrom) oder fix (Hallenmiete) sein. Die Einteilung nach Zurechenbarkeit ist von der Einteilung nach Kostenverhalten unabhängig.')
n('verhalten',2,'Bonus: Variable Stückkosten 24 €, Menge 750. Berechnen Sie die variablen Gesamtkosten.',18000,'Variable Kosten = 24 €/Stück (variable Stückkosten) · 750 Stück (Produktionsmenge) = **18.000 €**.',bonus=True)
tx('verhalten',3,'Bonus: Nennen Sie eine Situation, in der Fixkosten nicht dauerhaft konstant bleiben.','Beim Ausbau der Kapazität muss etwa eine zusätzliche Halle angemietet werden. Es können sprungfixe Kosten entstehen.',bonus=True)

module('erfolg','Umsatz, Kosten & Betriebsergebnis','💶','Wie entsteht das Betriebsergebnis?',
 'Der **Umsatz** entsteht aus Verkaufspreis und Absatzmenge. Die **Gesamtkosten** sind die Summe aus variablen und fixen Gesamtkosten. Das **Betriebsergebnis** ergibt sich aus Umsatzerlösen abzüglich Gesamtkosten.',
 ['**Umsatz = Verkaufspreis · Absatzmenge**','**Gesamtkosten = variable Stückkosten · Menge + Fixkosten**','**Betriebsergebnis = Umsatz − Gesamtkosten**'],
 'LoopLab: 400 FlexDock · 46 € = 18.400 € Umsatz. Kosten: 400 · 22 € + 6.400 € = 15.200 €. Betriebsergebnis = 3.200 € Gewinn.','kostenbaum',['Umsatz','Gesamtkosten','Betriebsergebnis','Stückkosten'])
s('erfolg',1,'Welche Größe muss von den Umsatzerlösen abgezogen werden?','Gesamtkosten',['Fixkosten je Stück','Gesamtkosten','Nur das Fertigungsmaterial'],'Betriebsergebnis = Umsatzerlöse − Gesamtkosten.')
tf('erfolg',1,'Sind Umsatzerlöse von 20.000 € größer als Gesamtkosten von 17.000 €, ergibt sich ein Gewinn von 3.000 €.',True,'20.000 € (Umsatz) − 17.000 € (Gesamtkosten) = **3.000 € Gewinn**.')
n('erfolg',2,'400 FlexDock werden zu je 46 € verkauft. Berechnen Sie den Umsatz.',18400,'Umsatz = 400 Stück (Absatzmenge) · 46 €/Stück (Verkaufspreis) = **18.400 €**.')
n('erfolg',2,'400 Stück, variable Stückkosten 22 €, Fixkosten 6.400 €. Berechnen Sie die Gesamtkosten.',15200,'Gesamtkosten = 400 Stück (Produktionsmenge) · 22 €/Stück (variable Stückkosten) + 6.400 € (Fixkosten) = **15.200 €**.')
n('erfolg',2,'Umsatz 18.400 €, Gesamtkosten 15.200 €. Bestimmen Sie das Betriebsergebnis.',3200,'Betriebsergebnis = 18.400 € (Umsatz) − 15.200 € (Gesamtkosten) = **3.200 € Gewinn**.')
order('erfolg',2,'Ordnen Sie die Schritte einer Erfolgsrechnung.', ['Umsatz ermitteln','Variable Gesamtkosten ermitteln','Fixkosten berücksichtigen','Betriebsergebnis berechnen'], 'Zuerst Erlöse, dann variable Kosten, dann fixe Kosten, abschließend Betriebsergebnis.')
tx('erfolg',3,'Ein Unternehmen steigert die Absatzmenge, die Fixkosten bleiben gleich. Erläutern Sie unter welcher Bedingung das Betriebsergebnis steigt.','Bei unverändertem Verkaufspreis und proportionalen variablen Kosten steigt das Ergebnis, wenn der Stückdeckungsbeitrag positiv ist.')
tx('erfolg',3,'Beurteilen Sie die Aussage: „Mehr Umsatz bedeutet immer mehr Gewinn.“','Falsch. Das Ergebnis hängt auch von zusätzlichen variablen und möglicherweise neuen fixen Kosten ab. Bei negativem Stückdeckungsbeitrag kann mehr Absatz den Verlust erhöhen.')
n('erfolg',2,'Bonus: 500 Stück zu 30 €, variable Kosten je Stück 19 €, Fixkosten 4.000 €. Berechnen Sie den Gewinn.',1500,'Gewinn = 500 Stück (Absatzmenge) · 30 €/Stück (Verkaufspreis) − 500 Stück (Produktionsmenge) · 19 €/Stück (variable Stückkosten) − 4.000 € (Fixkosten) = **1.500 €**.',bonus=True)
tx('erfolg',3,'Bonus: Wie wirkt ein Anstieg der Fixkosten auf das Betriebsergebnis bei unveränderter Menge?','Es sinkt in genau der Höhe der zusätzlichen Fixkosten, sofern Umsatz und variable Kosten konstant bleiben.',bonus=True)

module('kurz','Kurzfristige Preisuntergrenze & Deckungsbeitrag','🎯','Wo endet ein tragfähiger Verkaufspreis?',
 'Die **kurzfristige Preisuntergrenze** entspricht den **variablen Stückkosten**. Der **Stückdeckungsbeitrag** ist die Differenz zwischen Verkaufspreis und variablen Stückkosten. Ein positiver Deckungsbeitrag trägt zur Fixkostendeckung bei; bei genau null ändert sich das Betriebsergebnis unter den Modellannahmen nicht.',
 ['**db = p − kv**','**kurzfristige PUG = kv**','**p > kv:** positiver Deckungsbeitrag','**p = kv:** Deckungsbeitrag 0','**p < kv:** negativer Deckungsbeitrag'],
 'FlexDock: 46 € Verkaufspreis − 22 € variable Stückkosten = 24 € Stückdeckungsbeitrag. Bei 22 € ist die kurzfristige Preisuntergrenze erreicht.','balken-hell',['Kurzfristige Preisuntergrenze','Stückdeckungsbeitrag','Gesamtdeckungsbeitrag'])
s('kurz',1,'Was bildet die kurzfristige Preisuntergrenze?','Variable Stückkosten',['Fixkosten','Variable Stückkosten','Gesamte Selbstkosten'],'Die kurzfristige Preisuntergrenze ist gleich den variablen Stückkosten.')
tf('kurz',1,'Bei einem Verkaufspreis genau in Höhe der variablen Stückkosten ist der Stückdeckungsbeitrag null.',True,'db = p − kv = 0.')
n('kurz',2,'Ein FlexDock wird für 46 € verkauft und hat variable Stückkosten von 22 €. Berechnen Sie den Stückdeckungsbeitrag.',24,'Stückdeckungsbeitrag = 46 € (Verkaufspreis) − 22 € (variable Stückkosten) = **24 €/Stück**.',unit='€/Stück')
n('kurz',2,'Variable Gesamtkosten 10.800 €, Menge 450 Stück. Wie hoch ist die kurzfristige Preisuntergrenze?',24,'Kurzfristige PUG = 10.800 € (variable Gesamtkosten) ÷ 450 Stück (Menge) = **24 €/Stück**.',unit='€/Stück')
n('kurz',2,'Ein Produkt erzielt 11 € Stückdeckungsbeitrag bei 360 verkauften Stück. Ermitteln Sie den Gesamtdeckungsbeitrag.',3960,'Gesamtdeckungsbeitrag = 11 €/Stück (db) · 360 Stück (Absatz) = **3.960 €**.')
match('kurz',2,'Ordnen Sie das jeweilige Preisverhältnis der Wirkung zu.',{'p > kv':'positiver Stückdeckungsbeitrag','p = kv':'Stückdeckungsbeitrag = 0','p < kv':'negativer Stückdeckungsbeitrag'},'Die kurzfristige Preisuntergrenze ist der Grenzfall p = kv.')
tx('kurz',3,'Eine Kundin bietet 20 € für ein Teil mit variablen Stückkosten von 22 €. Beurteilen Sie den Verkauf bei freien Kapazitäten.','Der Stückdeckungsbeitrag beträgt 20 € − 22 € = −2 €. Jeder zusätzliche Verkauf verschlechtert das Ergebnis um 2 €; der Preis liegt unter der kurzfristigen Preisuntergrenze.')
tx('kurz',3,'Warum bedeutet ein positiver Stückdeckungsbeitrag nicht zwangsläufig Gewinn?','Der Stückdeckungsbeitrag dient zunächst zur Deckung der Fixkosten. Erst wenn der Gesamtdeckungsbeitrag die Fixkosten übersteigt, entsteht ein positiver Betriebserfolg.')
n('kurz',2,'Bonus: Bei kv = 18 € und p = 16 €: Wie hoch ist der Stückdeckungsbeitrag?',-2,'db = 16 € (Preis) − 18 € (variable Stückkosten) = **−2 €/Stück**.',unit='€/Stück',bonus=True)
tx('kurz',3,'Bonus: Unter welchen Voraussetzungen ist ein kurzfristiger Verkauf zwischen beiden Preisuntergrenzen sinnvoll?','Freie Kapazitäten, keine zusätzlichen Fixkosten, keine Verdrängung günstigerer Aufträge; positiver Deckungsbeitrag.',bonus=True)

module('lang','Langfristige Preisuntergrenze & Auslastung','📉','Warum verändert die Menge den Mindestpreis?',
 'Die **langfristige Preisuntergrenze** liegt bei den **gesamten Stückkosten/Selbstkosten**. Fixkosten verteilen sich auf die Anzahl der hergestellten und verkauften Stücke. Bei konstanten variablen Stückkosten sinken die fixen Stückkosten, wenn die Menge steigt (**Fixkostendegression**).',
 ['**Fixe Stückkosten = Fixkosten ÷ Menge**','**Selbstkosten je Stück = variable Stückkosten + fixe Stückkosten**','**Langfristige PUG = Selbstkosten je Stück**','Bei geringerem Beschäftigungsgrad steigt die langfristige PUG (im Modell).'],
 'FlexDock: 6.400 € Fixkosten ÷ 400 Stück = 16 €/Stück. Langfristige PUG = 22 € + 16 € = **38 €/Stück**.','auslastung',['Langfristige Preisuntergrenze','Fixkostendegression','Beschäftigungsgrad','Selbstkosten'])
s('lang',1,'Was bildet die langfristige Preisuntergrenze?','Gesamte Stückkosten / Selbstkosten',['Nur variable Stückkosten','Gesamte Stückkosten / Selbstkosten','Nur Fixkosten'],'Langfristig müssen variable und fixe Kosten gedeckt sein.')
tf('lang',1,'Bei gleichbleibenden Fixkosten und konstanten variablen Stückkosten sinkt die langfristige PUG bei steigender Menge.',True,'Die Fixkosten verteilen sich auf mehr Stück (Fixkostendegression).')
n('lang',2,'Monatliche Fixkosten 6.400 €, Produktion 400 Stück. Berechnen Sie die fixen Stückkosten.',16,'Fixe Stückkosten = 6.400 € (Fixkosten) ÷ 400 Stück (Menge) = **16 €/Stück**.',unit='€/Stück')
n('lang',2,'Variable Stückkosten 22 €, fixe Stückkosten 16 €. Wie hoch ist die langfristige Preisuntergrenze?',38,'Langfristige PUG = 22 € (variable Stückkosten) + 16 € (fixe Stückkosten) = **38 €/Stück**.',unit='€/Stück')
n('lang',2,'Fixkosten 6.400 €, variable Stückkosten 22 €, Menge 800. Ermitteln Sie die langfristige PUG.',30,'Langfristige PUG = 22 € (variable Stückkosten) + 6.400 € (Fixkosten) ÷ 800 Stück (Menge) = **30 €/Stück**.',unit='€/Stück')
order('lang',2,'Ordnen Sie die Berechnung der langfristigen PUG.', ['Fixkosten pro Zeitraum ermitteln','Fixkosten durch Stückzahl teilen','Variable Stückkosten addieren','Langfristige PUG benennen'], 'Die gesamte Stückkostenbasis besteht aus variablen und fixen Stückkosten.')
tx('lang',3,'Erläutern Sie, warum die kurzfristige PUG bei der Mengenerhöhung nicht sinkt, die langfristige hingegen schon.','Bei konstanten variablen Stückkosten bleibt die kurzfristige PUG unverändert. Die fixe Stückkostenkomponente der langfristigen PUG sinkt durch Verteilung der Fixkosten auf mehr Stück.')
tx('lang',3,'Ein Betrieb verkauft bei 200 Stück unter seinen Selbstkosten, aber oberhalb der variablen Stückkosten. Beurteilen Sie die langfristige Preisstrategie.','Der Verkauf bringt kurzfristig einen positiven Deckungsbeitrag, deckt die gesamten Kosten aber nicht. Dauerhaft muss die Preis- oder Kostenstruktur angepasst werden.')
n('lang',2,'Bonus: 360.000 € Fixkosten pro Jahr, sechs Einheiten, kv = 50.000 €. Langfristige PUG?',110000,'Langfristige PUG = 50.000 €/Einheit (variable Stückkosten) + 360.000 € (Jahresfixkosten) ÷ 6 Einheiten (Jahresmenge) = **110.000 €/Einheit**.',unit='€/Einheit',bonus=True)
tx('lang',3,'Bonus: Warum lässt sich die langfristige PUG nicht ohne Mengenangabe exakt berechnen, wenn nur Fixkosten vorliegen?','Weil die fixen Stückkosten von der hergestellten bzw. abgesetzten Menge abhängen.',bonus=True)

module('spaltung','Gemeinkosten in fix und variabel aufteilen','🧩','Welche Gemeinkosten zählen zur kurzfristigen Grenze?',
 'Für die kurzfristige Preisuntergrenze zählen **variable Einzelkosten** und **variable Gemeinkosten**. Häufig nimmt die Prüfung vereinfachend an, dass sämtliche Einzelkosten variabel sind. Ist nur ein fixer Anteil der Gemeinkosten angegeben, muss zuerst der variable Anteil berechnet werden.',
 ['**Variable GK = gesamte GK · variabler Anteil**','**Variabler Anteil = 100 % − fixer Anteil**','**Kurzfristige PUG = (variable Einzelkosten + variable GK) ÷ Menge**','**Langfristige PUG = (alle Einzelkosten + alle GK) ÷ Menge**'],
 'Beispiel: 12.000 € Einzelkosten, 8.000 € Gemeinkosten, davon 75 % fix, 500 Stück. Variable GK = 2.000 €; kurzfristige PUG = 28 €; langfristige PUG = 40 €.','kostenmatrix',['Kostenspaltung','Fixkostenanteil','Variable Gemeinkosten'])
s('spaltung',1,'Sind 80 % der Gemeinkosten fix, welcher Anteil ist variabel?','20 %',['80 %','20 %','0 %'],'100 % − 80 % (fix) = **20 % variabel**.')
tf('spaltung',1,'Bei der kurzfristigen PUG werden unter der Annahme vollständig variabler Einzelkosten auch variable Gemeinkosten berücksichtigt.',True,'Die variablen Stückkosten setzen sich aus variablen Einzelkosten und variablen Gemeinkosten zusammen.')
n('spaltung',2,'Die Gemeinkosten betragen 8.000 €, davon 75 % fix. Wie hoch sind die variablen Gemeinkosten?',2000,'Variable GK = 8.000 € (Gemeinkosten) · 25 % (variabler Anteil) = **2.000 €**.')
n('spaltung',2,'Einzelkosten 12.000 € (voll variabel), GK 8.000 € (75 % fix), 500 Stück. Kurzfristige PUG?',28,'Variable GK = 8.000 € (gesamte GK) · 25 % (variabler Anteil) = 2.000 €. Kurzfristige PUG = [12.000 € (variable EK) + 2.000 € (variable GK)] ÷ 500 Stück (Menge) = **28 €/Stück**.',unit='€/Stück')
n('spaltung',2,'Einzelkosten 12.000 €, Gemeinkosten 8.000 €, Menge 500. Langfristige PUG?',40,'Langfristige PUG = [12.000 € (Einzelkosten) + 8.000 € (Gemeinkosten)] ÷ 500 Stück (Absatzmenge) = **40 €/Stück**.',unit='€/Stück')
match('spaltung',2,'Ordnen Sie die Werte zu: GK = 10.000 €, davon 60 % fix.',{'Fixe GK':'6.000 €','Variable GK':'4.000 €','Alle GK':'10.000 €'},'Fixe GK = 10.000 € · 60 % = 6.000 €; variable GK = 10.000 € · 40 % = 4.000 €.')
tx('spaltung',3,'Ein Unternehmen setzt alle Gemeinkosten bei der kurzfristigen PUG an. Beurteilen Sie den Fehler.','Die kurzfristige PUG wäre zu hoch, wenn fixe Gemeinkosten einbezogen werden. Es sind nur die variablen Bestandteile relevant (sowie ggf. variable Einzelkosten).')
tx('spaltung',3,'Erläutern Sie, warum bei fixen Einzelkosten die Formel „alle Einzelkosten + variable GK“ nicht allgemein korrekt ist.','Fixe Einzelkosten dürfen für die kurzfristige PUG nicht berücksichtigt werden. Allgemein zählen nur die gesamten variablen Kosten, unabhängig von ihrer Einzel-/Gemeinkosteneigenschaft.')
n('spaltung',2,'Bonus: Gesamt-GK 15.000 €, davon 40 % fix. Ermitteln Sie die variablen GK.',9000,'Variable GK = 15.000 € (gesamte GK) · (100 % gesamt − 40 % fixer Anteil) = **9.000 €**.',bonus=True)
tx('spaltung',3,'Bonus: Wie beeinflusst eine Erhöhung des fixen GK-Anteils bei unveränderten gesamten GK die kurzfristige PUG?','Der variable GK-Anteil sinkt, damit sinkt – bei unveränderter Menge und variablen Einzelkosten – die kurzfristige PUG.',bonus=True)

module('zuschlag','Zuschlagskalkulation & Preisuntergrenzen','🧮','Vom Fertigungsmaterial zu den Selbstkosten',
 'Bei der **Zuschlagskalkulation** werden Gemeinkosten über Zuschlagssätze verteilt: Materialgemeinkosten auf Fertigungsmaterial, Fertigungsgemeinkosten auf Fertigungslöhne sowie Verwaltungs- und Vertriebsgemeinkosten meist auf die Herstellkosten. Anschließend lässt sich die langfristige PUG als Selbstkosten ermitteln.',
 ['**MGK = Fertigungsmaterial · MGK-Zuschlag**','**FGK = Fertigungslöhne · FGK-Zuschlag**','**Herstellkosten = Materialkosten + Fertigungskosten**','**VwGK/VtGK = Herstellkosten · Zuschlag**','**Selbstkosten = Herstellkosten + VwGK + VtGK**'],
 'Beispiel: FM 60 €, FL 30 €, MGK 20 %, FGK 50 %, VwGK 10 %, VtGK 5 % → HK 117 €, VwGK 11,70 €, VtGK 5,85 €, Selbstkosten **134,55 €**.','kostenbaum',['Zuschlagskalkulation','Materialgemeinkostenzuschlag','Fertigungsgemeinkostenzuschlag','Herstellkosten'])
s('zuschlag',1,'Auf welche Bezugsgröße wird der Fertigungsgemeinkostenzuschlag in der einfachen Zuschlagskalkulation angewandt?','Fertigungslöhne',['Fertigungslöhne','Selbstkosten','Nettoumsatz'],'FGK = Fertigungslöhne · FGK-Zuschlagssatz.')
tf('zuschlag',1,'In der üblichen FOS-Zuschlagskalkulation werden Verwaltungs- und Vertriebsgemeinkosten auf die Herstellkosten bezogen.',True,'Das ist die verwendete Bezugsgröße im hier behandelten Kalkulationsschema.')
n('zuschlag',2,'Fertigungsmaterial 60 €, MGK-Zuschlag 20 %. Berechnen Sie die Materialgemeinkosten.',12,'MGK = 60 € (Fertigungsmaterial) · 20 % (Zuschlag) = **12 €**.',unit='€/Stück')
n('zuschlag',2,'Fertigungslöhne 30 €, FGK-Zuschlag 50 %. Berechnen Sie die Fertigungsgemeinkosten.',15,'FGK = 30 € (Fertigungslöhne) · 50 % (Zuschlag) = **15 €**.',unit='€/Stück')
n('zuschlag',2,'FM 60 €, MGK 12 €, FL 30 €, FGK 15 €. Berechnen Sie die Herstellkosten.',117,'Herstellkosten = 60 € (FM) + 12 € (MGK) + 30 € (FL) + 15 € (FGK) = **117 €**.',unit='€/Stück')
n('zuschlag',2,'Herstellkosten 117 €, VwGK 10 %, VtGK 5 %. Ermitteln Sie die Selbstkosten.',134.55,'VwGK = 117 € (Herstellkosten) · 10 % (VwGK-Zuschlag) = 11,70 €. VtGK = 117 € (Herstellkosten) · 5 % (VtGK-Zuschlag) = 5,85 €. Selbstkosten = 117 € (HK) + 11,70 € (VwGK) + 5,85 € (VtGK) = **134,55 €**.',unit='€/Stück')
tx('zuschlag',3,'Ein Unternehmen addiert Gewinnaufschlag, Rabatt und Skonto zu den Selbstkosten, um die langfristige PUG zu berechnen. Beurteilen Sie das Vorgehen.','Falsch. Die langfristige PUG entspricht den Selbstkosten. Gewinn, Kundenskonto und Kundenrabatt gehören zur Verkaufspreiskalkulation, nicht zu den Kosten der PUG.')
tx('zuschlag',3,'Bei Selbstkosten von 134,55 € sind 80 % der Gemeinkosten fix. Beschreiben Sie den Weg zur kurzfristigen PUG.','Zuerst Einzelkosten ermitteln, dann gesamte GK = Selbstkosten − Einzelkosten; davon 20 % variable GK bestimmen und zu den variablen Einzelkosten addieren.')
n('zuschlag',2,'Bonus: Selbstkosten 134,55 €, Einzelkosten 90 €, GK 44,55 €, davon 20 % variabel. Kurzfristige PUG?',98.91,'Variable GK = 44,55 € (gesamte GK) · 20 % (variabler Anteil) = 8,91 €. Kurzfristige PUG = 90 € (variable EK) + 8,91 € (variable GK) = **98,91 €**.',unit='€/Stück',bonus=True)
tx('zuschlag',3,'Bonus: Weshalb muss man die Zuschlagsgrundlage bei jedem Gemeinkostenzuschlag beachten?','Weil gleiche Prozentsätze auf unterschiedliche Basen verschiedene Kosten ergeben; falsche Bezugsgrundlagen verfälschen die Selbstkosten und Preisuntergrenzen.',bonus=True)

module('preis','Drei Preiszonen & Entscheidungen','🚦','Preis unter, zwischen oder über den Grenzen?',
 'Die **Preisampel** vergleicht den Nettoverkaufspreis mit kurzfristiger und langfristiger Preisuntergrenze. Unterhalb der kurzfristigen PUG ist der Stückdeckungsbeitrag negativ. Zwischen beiden Grenzen besteht zwar ein positiver Deckungsbeitrag, aber keine volle Kostendeckung. Oberhalb der langfristigen PUG entsteht – bei der betrachteten Menge und Kostenstruktur – Stückgewinn.',
 ['**p < kurzfristige PUG:** negativ','**p = kurzfristige PUG:** db = 0','**kurzfristige PUG < p < langfristige PUG:** positive Fixkostendeckung, Stückverlust','**p = langfristige PUG:** Stückergebnis = 0','**p > langfristige PUG:** Stückgewinn'],
 'Für FlexDock gelten kurzfristige PUG 22 € und langfristige PUG 38 €. Ein Angebot von 31 € erzielt db = 9 €, aber Stückverlust = 7 €.','balken',['Preisampel','Stückergebnis','Stückverlust'])
s('preis',1,'p = 31 €, kurzfristige PUG = 22 €, langfristige PUG = 38 €. Welche Zone liegt vor?','Zwischen beiden Preisuntergrenzen',['Unter kurzfristiger PUG','Zwischen beiden Preisuntergrenzen','Über langfristiger PUG'],'31 € liegt über 22 €, aber unter 38 €.')
tf('preis',1,'Bei p = langfristiger PUG entsteht im betrachteten Modell gerade kein Stückgewinn.',True,'Der Verkaufspreis deckt dann genau die gesamten Stückkosten.')
n('preis',2,'p = 31 €, kv = 22 €. Wie hoch ist der Stückdeckungsbeitrag?',9,'db = 31 € (Preis) − 22 € (variable Stückkosten) = **9 €/Stück**.',unit='€/Stück')
n('preis',2,'p = 31 €, Selbstkosten 38 €. Wie hoch ist das Stückergebnis?',-7,'Stückergebnis = 31 € (Verkaufspreis) − 38 € (Selbstkosten) = **−7 €/Stück**.',unit='€/Stück')
match('preis',2,'Ordnen Sie die Angebotspreise (PUG kurz 22 €, PUG lang 38 €) zu.',{'19 €':'negativer Deckungsbeitrag','30 €':'positiver DB, Stückverlust','41 €':'Stückgewinn'},'19 < 22; 22 < 30 < 38; 41 > 38.')
mult('preis',2,'Welche Gründe sprechen bei 30 € für eine befristete Preisentscheidung?',['Positiver Stückdeckungsbeitrag','Freie Kapazitäten'],['Positiver Stückdeckungsbeitrag','Volle Deckung der Selbstkosten','Freie Kapazitäten','Fixkosten sind dadurch verschwunden'],'Bei 30 € sind 8 € Stückdeckungsbeitrag vorhanden, aber keine vollständige Kostendeckung.')
tx('preis',3,'Beurteilen Sie, ob LoopLab seinen regulären FlexDock-Preis dauerhaft von 46 € auf 30 € senken sollte.','Bei Selbstkosten von 38 € wäre der Preis dauerhaft nicht kostendeckend; eine befristete Entscheidung könnte nur unter besonderen Bedingungen vertretbar sein.')
tx('preis',3,'Erklären Sie, warum eine Empfehlung allein aus dem Vergleich p > kv bei vollen Kapazitäten nicht ausreicht.','Kapazitätsengpässe und entgangene Alternativaufträge verursachen Opportunitätskosten. Man muss die beste Verwendung der knappen Kapazität vergleichen.')
n('preis',2,'Bonus: p = 25 €, kv = 22 €, Selbstkosten 38 €. Ermitteln Sie das Stückergebnis.',-13,'Stückergebnis = 25 € (Preis) − 38 € (Selbstkosten) = **−13 €/Stück**.',unit='€/Stück',bonus=True)
tx('preis',3,'Bonus: Warum ist die kurzfristige PUG keine sinnvolle dauerhafte Preisstrategie?','Sie deckt nur variable Kosten, nicht aber die dauerhaft anfallenden Fixkosten.',bonus=True)

module('zusatz','Zusatzauftrag bei freien Kapazitäten','🛒','Wann ist ein Preis unter Selbstkosten sinnvoll?',
 'Ein **Zusatzauftrag** nutzt freie Kapazitäten. Entscheidend ist dessen **zusätzlicher Deckungsbeitrag**, wenn keine neuen Fixkosten entstehen und kein besserer Auftrag verdrängt wird. Diese Entscheidung ist eine Anwendung der kurzfristigen PUG, ersetzt jedoch keine langfristig kostendeckende Preispolitik.',
 ['**Zusätzlicher DB = Auftragsmenge · (Angebotspreis − variable Stückkosten)**','**Ergebnis mit Auftrag = bisheriges Ergebnis + zusätzlicher DB**','Zusätzliche fixe Kosten müssen gegebenenfalls zusätzlich abgezogen werden.'],
 'LoopLab erhält für 100 FlexDock 29 € statt regulär 46 €. Bei kv = 22 € ergibt sich ein zusätzlicher DB von 700 €, falls keine weiteren Kosten entstehen.','comic',['Zusatzauftrag','Freie Kapazität','Opportunitätskosten'])
s('zusatz',1,'Welcher Wert ist für einen Zusatzauftrag bei freien Kapazitäten und unveränderten Fixkosten zentral?','Zusätzlicher Deckungsbeitrag',['Gesamte historische Fixkosten','Zusätzlicher Deckungsbeitrag','Nur der Listenpreis'],'Der zusätzliche Deckungsbeitrag zeigt die Ergebniswirkung.')
tf('zusatz',1,'Ein Zusatzauftrag mit positivem Deckungsbeitrag verbessert bei freien Kapazitäten und unveränderten Fixkosten das Ergebnis.',True,'Der Auftrag trägt zusätzlich zur Fixkostendeckung oder zum Gewinn bei.')
n('zusatz',2,'100 zusätzliche FlexDock, Angebotspreis 29 €, kv = 22 €. Gesamtdeckungsbeitrag des Zusatzauftrags?',700,'Zusätzlicher DB = 100 Stück (Auftragsmenge) · [29 € (Preis) − 22 € (kv)] = **700 €**.')
n('zusatz',2,'Bisheriger Gewinn 3.200 €, zusätzlicher DB 700 €, keine Mehrfixkosten. Neuer Gewinn?',3900,'Neuer Gewinn = 3.200 € (bisheriges Ergebnis) + 700 € (zusätzlicher DB) = **3.900 €**.')
n('zusatz',2,'Zusätzlicher DB 700 €, aber auftragsbedingte Fixkosten 250 €. Wie stark verbessert sich das Ergebnis?',450,'Ergebnisänderung = 700 € (zusätzlicher DB) − 250 € (zusätzliche Fixkosten) = **450 €**.')
match('zusatz',2,'Ordnen Sie die Bedingung ihrer Bedeutung zu.',{'Freie Kapazität':'Kein besserer Auftrag verdrängt','Keine Mehrfixkosten':'Nur variable Kosten entstehen zusätzlich','p > kv':'Positiver Stückdeckungsbeitrag'},'Zusatzaufträge werden nach zusätzlichen Erlösen und Kosten beurteilt.')
tx('zusatz',3,'Ein Auftrag über 100 Stück für 20 € wird bei kv = 22 € angeboten. Beurteilen Sie die Annahme.','db = −2 € je Stück, insgesamt −200 €. Der Auftrag würde das Ergebnis verschlechtern und sollte unter den Modellannahmen nicht angenommen werden.')
tx('zusatz',3,'Ein attraktiver Großauftrag verdrängt einen bisherigen Auftrag mit höherem Stückdeckungsbeitrag. Warum ist „p > kv“ allein keine ausreichende Entscheidung?','Die verdrängte Alternative bringt entgangenen Deckungsbeitrag. Bei Kapazitätsengpass muss der zusätzliche Nutzen gegen Opportunitätskosten abgewogen werden.')
n('zusatz',2,'Bonus: Angebot für 300 Stück zu 28 €, kv = 22 €. Zusätzlicher Gesamt-DB?',1800,'Zusätzlicher Gesamt-DB = 300 Stück (Zusatzauftrag) · [28 € (Angebotspreis) − 22 € (variable Stückkosten)] = **1.800 €**.',bonus=True)
tx('zusatz',3,'Bonus: Erklären Sie den Unterschied zwischen Zusatzauftrag und allgemeiner Senkung des Listenpreises.','Ein Zusatzauftrag ist eine begrenzte Einzelentscheidung mit freien Kapazitäten. Eine allgemeine Listenpreissenkung betrifft häufig sämtliche Verkäufe und verändert das gesamte Betriebsergebnis.',bonus=True)

module('elimination','Produktelimination & Fixkostendeckung','🌱','Warum bleibt ein Verlustprodukt manchmal im Programm?',
 'Bei der **Produktelimination** stellt sich die Frage, ob die Aufgabe eines Produkts das gesamte Betriebsergebnis verbessert. Ein Produkt kann laut Vollkostenrechnung **Stückverlust** ausweisen und trotzdem einen **positiven Deckungsbeitrag** erzielen. Bleiben die zugeordneten Fixkosten bei der Elimination bestehen, verschlechtert der Wegfall dieses Deckungsbeitrags das Ergebnis.',
 ['**db = Preis − variable Stückkosten**','**Gesamt-DB = db · Absatzmenge**','**Betriebsergebnis = Gesamt-DB − verbleibende Fixkosten**','Vor der Elimination prüfen: Welche Fixkosten entfallen tatsächlich?'],
 'Ein LoopLab-Zubehörteil hat p = 24 €, kv = 16 €, 1.000 Verkäufe und 9.000 € Fixkosten. Mit Produkt: −1.000 €. Ohne Produkt, wenn die Fixkosten bleiben: −9.000 €. Behalten verbessert um 8.000 €.','kostenmatrix',['Produktelimination','Vollkostenrechnung','Teilkostenrechnung'])
s('elimination',1,'Bei der Produktelimination ist welche Information besonders wichtig?','Ob Fixkosten entfallen',['Ob Fixkosten entfallen','Nur der Materialname','Die Farbe des Produkts'],'Entscheidend ist, welche Kosten nach der Einstellung tatsächlich verbleiben.')
tf('elimination',1,'Ein Stückverlust nach Vollkostenrechnung beweist immer, dass ein Produkt gestrichen werden sollte.',False,'Falsch. Entscheidend sind der Deckungsbeitrag und die durch die Elimination vermeidbaren Kosten.')
n('elimination',2,'Ein Zubehörteil wird für 24 € verkauft, kv = 16 €. Berechnen Sie den Stückdeckungsbeitrag.',8,'Stückdeckungsbeitrag = 24 € (Verkaufspreis) − 16 € (variable Stückkosten) = **8 €/Stück**.',unit='€/Stück')
n('elimination',2,'Stückdeckungsbeitrag 8 €, Absatz 1.000 Stück. Gesamtdeckungsbeitrag?',8000,'Gesamt-DB = 8 €/Stück (db) · 1.000 Stück (Absatzmenge) = **8.000 €**.')
n('elimination',2,'Gesamt-DB 8.000 €, Fixkosten 9.000 €. Betriebsergebnis mit Produkt?',-1000,'Betriebsergebnis = 8.000 € (Gesamt-DB) − 9.000 € (Fixkosten) = **−1.000 €**.')
n('elimination',2,'Das Produkt wird gestrichen; Fixkosten von 9.000 € bleiben. Betriebsergebnis ohne Produkt?',-9000,'Betriebsergebnis ohne Produkt = 0 € (Deckungsbeitrag) − 9.000 € (Fixkosten) = **−9.000 €**.')
tx('elimination',3,'Positionieren Sie sich zur Elimination: Mit Produkt −1.000 €, ohne Produkt −9.000 €.','Behalten, sofern keine bessere Alternative vorliegt. Der positive Gesamt-DB von 8.000 € reduziert den Verlust. Die Elimination würde das Ergebnis um 8.000 € verschlechtern.')
tx('elimination',3,'Wie ändert sich die Entscheidung, wenn bei Elimination alle 9.000 € Fixkosten tatsächlich entfallen?','Mit Produkt −1.000 €, ohne Produkt 0 €. Eine Elimination würde das Ergebnis um 1.000 € verbessern, sofern keine weiteren Effekte eintreten.')
n('elimination',2,'Bonus: Positiver DB 6 €/Stück, 2.000 Stück; fixe Kosten bleiben. Ergebnisverschlechterung bei Streichung?',12000,'Entgangener DB = 6 €/Stück (Stückdeckungsbeitrag) · 2.000 Stück (Absatzmenge) = **12.000 €**.',bonus=True)
tx('elimination',3,'Bonus: Warum kann die Vollkostenrechnung eine Produktentscheidung in die falsche Richtung lenken?','Zugeordnete fixe Gemeinkosten erscheinen als Stückkosten, obwohl sie bei der Elimination ggf. weiter bestehen. Die DB-Rechnung zeigt den Beitrag zur Fixkostendeckung.',bonus=True)

# Abschlusstest mit 12 Fragen 3/6/3, keine Bonus
module('test','Abschlusstest – Preisuntergrenzen','🏆','Testen Sie die wichtigsten Kompetenzen.',
 'Der Abschlusstest greift die wesentlichen Kompetenzen auf. Antworten werden nach denselben Regeln wie in den Übungen geprüft; bei Begründungsaufgaben vergleichen Sie Ihre Formulierung selbst mit dem Lösungsbeispiel.',
 ['Kosten einteilen und berechnen','Preisuntergrenzen bestimmen','Deckungsbeiträge interpretieren','Kosten- und Preissituationen begründet beurteilen'],
 'Am Ende können Sie Ihre bearbeiteten Aufgaben und Antworten als PDF ausgeben.','balken-hell',[])
s('test',1,'Welche Größe entspricht der kurzfristigen PUG?','Variable Stückkosten',['Fixkosten','Variable Stückkosten','Herstellkosten plus Gewinn'],'Kurzfristige PUG = variable Stückkosten.')
s('test',1,'Welche Größe entspricht der langfristigen PUG?','Selbstkosten je Stück',['Nur variable GK','Nur Fixkosten','Selbstkosten je Stück'],'Langfristig müssen alle Kosten je Stück gedeckt sein.')
tf('test',1,'Bei p = kv ist der Stückdeckungsbeitrag gleich null.',True,'db = p − kv = 0.')
n('test',2,'Fixkosten 4.800 €, Menge 300, variable Stückkosten 18 €. Langfristige PUG?',34,'PUG lang = 18 € (kv) + 4.800 € (Fixkosten) ÷ 300 (Menge) = **34 €**.',unit='€/Stück')
n('test',2,'Gesamte Gemeinkosten 12.000 €, davon 65 % fix. Wie hoch sind die variablen GK?',4200,'Variable GK = 12.000 € (GK) · 35 % (variabler Anteil) = **4.200 €**.')
n('test',2,'Variable Einzelkosten 8.000 €, variable GK 2.000 €, Menge 500. Kurzfristige PUG?',20,'PUG kurz = [8.000 € (variable EK) + 2.000 € (variable GK)] ÷ 500 Stück (Menge) = **20 €**.',unit='€/Stück')
n('test',2,'p = 35 €, kv = 22 €. Stückdeckungsbeitrag?',13,'db = 35 € (Preis) − 22 € (kv) = **13 €/Stück**.',unit='€/Stück')
n('test',2,'250 Stück mit Stückdeckungsbeitrag 13 €. Gesamtdeckungsbeitrag?',3250,'Gesamt-DB = 250 Stück (Absatzmenge) · 13 €/Stück (Stückdeckungsbeitrag) = **3.250 €**.')
match('test',2,'Ordnen Sie die Kostentypen zu.',{'Hallenmiete':'Fixe Gemeinkosten','Aluminium je Stück':'Variable Einzelkosten','Maschinenstrom je Stück, gemeinsam':'Variable Gemeinkosten'},'Unterscheiden Sie die Zurechenbarkeit und die Beschäftigungsabhängigkeit.')
tx('test',3,'Ein Unternehmen verkauft dauerhaft unter den Selbstkosten, aber über den variablen Stückkosten. Beurteilen Sie die langfristige Situation.','Kurzfristig besteht ein positiver Deckungsbeitrag, langfristig werden die gesamten Kosten nicht gedeckt. Eine dauerhafte Lösung erfordert eine Anpassung von Preis, Menge oder Kosten.')
tx('test',3,'Ein Produkt hat laut Vollkostenrechnung Verlust, erzielt aber positiven Gesamt-DB. Die fixen Kosten bleiben bei Streichung bestehen. Treffen und begründen Sie eine Entscheidung.','Das Produkt sollte grundsätzlich beibehalten werden, sofern keine wirtschaftlich bessere Alternative besteht; sein positiver DB reduziert den Verlust bzw. erhöht den Gewinn.')
tx('test',3,'Erläutern Sie die Wirkung einer Halbierung der Menge bei konstanten Fixkosten und variablen Stückkosten.','Fixe Stückkosten verdoppeln sich; die langfristige PUG steigt. Die kurzfristige PUG bleibt konstant, weil sich kv nicht ändert.')

